#!/usr/bin/env node
// Compile reviewed lesson modules into one browser request at release time.
import {writeFile} from 'node:fs/promises';
import {plan} from './plan-native-english-redesign.mjs';
import {editorialIssues} from './test-native-editorial-quality.mjs';

const rows=plan().rows;
const missing=rows.filter(row=>row.status!=='draft-needs-editorial-review');
if(missing.length||editorialIssues.length){
  console.error(`BLOCKED: ${missing.length} missing lessons; ${editorialIssues.length} editorial issues.`);
  process.exit(1);
}

const entries=await Promise.all(rows.map(async row=>{
  const filename=`lesson-${String(row.number).padStart(3,'0')}.mjs`;
  const draft=(await import(new URL(`../natural-english/${filename}`,import.meta.url))).default;
  if(draft.revision!==2)throw new Error(`${filename}: expected revision 2`);
  return [row.id,draft];
}));
const output=new URL('../natural-english/editorial-lessons.mjs',import.meta.url);
const source=`// Generated by tools/build-native-editorial-bundle.mjs. Do not edit by hand.\nexport default ${JSON.stringify(Object.fromEntries(entries))};\n`;
await writeFile(output,source);
console.log(`Built ${entries.length} reviewed lessons into one browser module (${Buffer.byteLength(source)} bytes).`);
